def f(N: int, F: int, info: List[Tuple[int, List[str]]]):
    '''
    N: an integer
    F: an integer
    info: a list of tuples, each containing an integer and a list of strings
    '''
    result = 0
    for count, items in info:
        if count > F:
            continue
        for item in items:
            if len(item) > F:
                break
        else:
            result += 1
    return result
